using System;
using System.IO;
using MassiveArmy.Industrial;
static class ShipbuildingChecks {
 static int checks;static void Check(bool condition,string name){if(!condition)throw new Exception(name);Console.WriteLine("PASS "+name);checks++;}
 static IndustrialCommand C(IndustrialActor actor,string kind,long source=0,long target=0,string item=null,string definition=null,string input=null)=>new IndustrialCommand{sequence=actor.lastSequence+1,kind=kind,source=source,target=target,item=item,definition=definition,operationRole=input};
 static void Main(){
  var data=new IndustrialWorld();var actor=data.Register(1,new FramePose{body=1});var other=data.Register(2,new FramePose{body=1});string file=Path.GetFullPath("TestResults/Planetary/ModularShip/recovery-"+Guid.NewGuid().ToString("N")+".xml");Directory.CreateDirectory(Path.GetDirectoryName(file));
  using(var authority=new IndustrialAuthority(data,file)){
   var init=C(actor,"ship-initialize");Check(authority.Execute(1,init).accepted,"Starter ship initialized through authoritative journal");Check(!authority.Execute(1,init).accepted&&data.ships.Count==1,"Repeated initialization cannot duplicate the starter ship");
   var ship=data.Ship(1);ship.UpdatePower();Check(ship.modules.Count==10&&ship.PoweredFraction("main-engine")==1&&ship.PoweredFraction("cockpit")==1,"Starter contains connected walkable sections and powered systems");
   var corridor=ship.modules.Find(m=>m.definition=="corridor");var cockpit=ship.modules.Find(m=>m.definition=="cockpit");Check(Math.Abs(corridor.pose.z-16)<1e-8&&Math.Abs(cockpit.pose.z-30)<1e-8,"Authored sockets reproduce the established ramp-to-cockpit frame");
   var engine=ship.modules.Find(m=>m.definition=="main-engine");Check(engine.pose.yaw==0,"Main engine exhaust points aft after socket alignment");
   Check(!authority.Execute(1,C(actor,"ship-remove",1)).accepted,"Root section cannot be dismantled");Check(!authority.Execute(1,C(actor,"ship-remove",corridor.id)).accepted,"Structural parents cannot be removed before their children");
   var add=C(actor,"ship-place",1,item:"engineering",definition:"engineering",input:"aft");Check(!authority.Execute(1,add).accepted,"Missing resources reject construction before mutation");actor.inventory.Add("hull-panel",12);actor.inventory.Add("electronics",2);long panels=actor.inventory.Count("hull-panel");
   Check(authority.Execute(1,add).accepted,"Paid engineering section snaps to compatible side socket");var room=ship.modules[ship.modules.Count-1];Check(actor.inventory.Count("hull-panel")==panels-12&&room.paid.Count==2,"Construction records exactly the extracted components");Check(!authority.Execute(1,add).accepted&&actor.inventory.Count("hull-panel")==panels-12,"Duplicate placement cannot spend twice");
   Check(!authority.Execute(2,C(other,"ship-place",1,item:"engineering",definition:"engineering",input:"aft")).accepted,"Another actor cannot modify an unowned ship");
   var core=ship.modules.Find(m=>m.definition=="power-core");Check(authority.Execute(1,C(actor,"ship-unwire",core.id,engine.id)).accepted,"Core-to-engine cable can be disconnected");ship.UpdatePower();Check(ship.PoweredFraction("main-engine")==.5,"Disconnected engine loses power without deleting it");
   actor.inventory.Add("wire",100);var wire=C(actor,"ship-wire",core.id,engine.id);wire.route=new System.Collections.Generic.List<FramePose>{ShipModules.P(18,3,-25),ShipModules.P(26,3,-25)};Check(authority.Execute(1,wire).accepted,"Power wiring accepts intermediate route points and consumes wire");ship.UpdatePower();Check(ship.PoweredFraction("main-engine")==1,"Reconnected engine regains power");Check(!authority.Execute(1,C(actor,"ship-wire",core.id,engine.id)).accepted,"A consumer cannot receive duplicate power connections");
   data.ShipActionValidator=(a,s,c)=>"Occupied";long rev=ship.revision;Check(!authority.Execute(1,C(actor,"ship-remove",room.id)).accepted&&ship.revision==rev,"Runtime occupancy/access validation runs before mutation");data.ShipActionValidator=null;
   Check(authority.Execute(1,C(actor,"ship-remove",room.id)).accepted&&actor.inventory.Count("hull-panel")==panels,"Dismantling returns the actual paid construction receipt");
   data.creativeMode=true;Check(authority.Execute(1,C(actor,"ship-place",1,item:"engineering",definition:"engineering",input:"aft")).accepted,"Creative construction requires no resources");room=ship.modules[ship.modules.Count-1];Check(room.paid.Count==0,"Creative builds have no refundable paid resources");Check(authority.Execute(1,C(actor,"ship-remove",room.id)).accepted&&actor.inventory.Count("hull-panel")==panels,"Creative dismantling cannot mint components");data.creativeMode=false;
   authority.Save();var remove=C(actor,"ship-unwire",core.id,engine.id);Check(authority.Execute(1,remove).accepted,"Post-snapshot ship changes enter the journal");
  }
  var recovered=IndustrialAuthority.Load(file);var restored=recovered.Ship(1);restored.UpdatePower();Check(restored.modules.Count==10&&restored.PoweredFraction("main-engine")==.5,"Crash recovery retains sections, wiring and power state");var roundtrip=IndustrialAuthority.Restore(IndustrialAuthority.Snapshot(recovered));Check(roundtrip.Ship(1).revision==restored.revision&&roundtrip.Ship(1).wires.Count==restored.wires.Count,"Versioned snapshot preserves assembly revisions and cable routes");File.WriteAllText("TestResults/Planetary/ModularShip/definitions.json",System.Text.Json.JsonSerializer.Serialize(ShipModules.Definitions,new System.Text.Json.JsonSerializerOptions{IncludeFields=true}));Console.WriteLine(checks+" shipbuilding checks passed");
 }
}
